      "rawText": "首页 > 科学普及 > 工作动态 9 月 13 日 ，中国科学院云南天文台在全国科普月期间举办亲子天文公益科普活动，面向5至9 岁儿童及家庭开启趣味天文启蒙之旅。 活动设置科学家互动讲座、实地参观、天文观测等环节 ，让 孩子们近距离探索宇宙奥秘 ，学习 科学知识 。 活动中，云南天文台原台长、研究员李焱带来专题分享《少儿天文知识启蒙》。李焱结合天文科研经验，贴合孩童认知特点，围绕太阳、月亮、星辰等问题展开讲解 。 现场互动氛围热烈，小朋友们踊跃提问 ，李焱逐一解答。 随后，亲子家庭在讲解员带领下开启天文台沉浸式研学。 大家走进天象厅观看球幕星空电影，沉浸式领略宇宙壮阔；观摩古老日晷，了解古人的天文计时智慧；在工作人员指导下，孩子们通过科普望远镜观测太阳、探寻太阳黑子，感受天文魅力。 活动以趣味化、沉浸式的方式，引导孩子从被动听讲转变为主动探索，为孩子们搭建了优质天文启蒙平台。 9月13日，中国科学院云南天文台在全国科普月期间举办亲子天文公益科普活动，面向5至9岁儿童及家庭开启趣味天文启蒙之旅。活动设置科学家互动讲座、实地参观、天文观测等环节，让孩子们近距离探索宇宙奥秘，学习科学知识。活",
