  "displayBriefingHtml": "\n    <div class=\"brief-display\">\n      <h3>CGTN Tech Desk Daily Radar <small>V3</small></h3>\n      <p><strong>ChenChen 今日中国科技热点</strong>｜Reporter Mode｜硬科技优先</p>\n      <p>日期：2026-09-14｜生成时间：2026/9/14 20:55:58｜抓取时间范围：00:00–当前时间</p>\n      <p>数据统计：抓取总数 2458｜确认今日 73｜国际背景 8</p>\n      <h4>本次更新</h4>\n      <p>新增核心线索：国内 11 条｜国际 0 条<br>延续跟踪线索：国内 62 条｜国际 8 条<br>本次有新增核心线索，优先核验新增项的一手来源和可视化素材。</p>\n      <h4>最值得关注</h4>\n      \n    <article class=\"brief-item\">\n      <strong>1. [2026-09-14] 2026年广西科技计划拟立项名单公示</strong>\n      <span>新浪科技｜2026-09-14｜<a href=\"https://finance.sina.com.cn/tech/discovery/2026-09-14/doc-inirveaq9284863.shtml\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <span>硬科技优先级：90｜记者分：192｜需核验来源</span>\n      <p>报道角度：Show whether the robot is moving from demo to deployment, using embodied intelligence beyond demonstration, orders, operating scenarios and safety as evidence. For this item, test the claim behind “2026年广西科技计划拟立项名单公示” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>2. [2026-09-14] 超越高通！AMD成为全球第三大无晶圆半导体公司</strong>\n      <span>新浪科技｜2026-09-14｜<a href=\"https://finance.sina.com.cn/tech/discovery/2026-09-14/doc-inirtwih7319546.shtml\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <span>硬科技优先级：95｜记者分：200｜需核验来源</span>\n      <p>报道角度：Report beyond the announcement: verify yield, scale, customers and how manufacturing capability and bottlenecks affects industrial resilience. For this item, test the claim behind “超越高通！AMD成为全球第三大无晶圆半导体公司” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>3. [2026-09-14] 上海落子太空算力：2030年建成全球天基算力网 | 国家未来产业地图</strong>\n      <span>网易科技｜2026-09-14｜<a href=\"https://www.163.com/dy/article/L6Q9UT120534A4SC.html\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <span>硬科技优先级：90｜记者分：199｜需核验来源</span>\n      <p>报道角度：Link the story to mission capability and commercial sustainability, then verify payload, mission economics, regulation, safety and practical service scenarios. For this item, test the claim behind “上海落子太空算力：2030年建成全球天基算力网 | 国家未来产业地图” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>4. [2026-09-14] 当GPT-6能让机器人拿起筷子，留给具身模型的窗口期还剩多久？</strong>\n      <span>新浪科技｜2026-09-14｜<a href=\"https://finance.sina.com.cn/stock/t/2026-09-14/doc-inirtwin4909545.shtml\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <span>硬科技优先级：95｜记者分：197｜需核验来源</span>\n      <p>报道角度：Frame this as an AI deployment story about model capability, access and ecosystem effects, separating product claims from evidence of real-world adoption. For this item, test the claim behind “当GPT-6能让机器人拿起筷子，留给具身模型的窗口期还剩多久？” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>5. [2026-09-14] 全国网络安全标准化技术委员会发布《人工智能安全治理框架 3.0》</strong>\n      <span>新浪科技｜2026-09-14｜<a href=\"https://finance.sina.com.cn/tech/digi/2026-09-14/doc-inirveas7203527.shtml\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <span>硬科技优先级：85｜记者分：185｜需核验来源</span>\n      <p>报道角度：Frame the policy through standards, implementation and international rule-setting, identifying what changes in practice for companies, researchers and international partners. For this item, test the claim behind “全国网络安全标准化技术委员会发布《人工智能安全治理框架 3.0》” against primary-source evidence.</p>\n    </article>\n  \n      <h4>国际科技背景</h4>\n      \n    <article class=\"brief-item\">\n      <strong>1. Anthropic's Amodei says China presents 'toughest dilemma' for his proposed AI slowdown</strong>\n      <span>时间：Sun, 13 Sep 2026 16:39:24 GMT｜来源：CNBC Technology｜<a href=\"https://www.cnbc.com/2026/09/13/china-dilemma-ai-slowdown-anthropic.html\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <p>Ask whether this changes China’s AI competitiveness through AI applications, foundation models, agents and governance, and identify users, costs, safeguards and export relevance. For this item, test the claim behind “Anthropic's Amodei says China presents 'toughest dilemma' for his propos” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>2. Xi says China will take lead to foster AI, tech cooperation among BRICS countries</strong>\n      <span>时间：Sun, 13 Sep 2026 16:38:45 GMT｜来源：CNBC Technology｜<a href=\"https://www.cnbc.com/2026/09/13/china-xi-ai-tech-brics.html\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <p>Turn the item into a reporting test of AI applications, foundation models, agents and governance: capability, implementation, economic value and regulatory consequences. For this item, test the claim behind “Xi says China will take lead to foster AI, tech cooperation among BRICS ” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>3. Nvidia's Groq acquihire is on the DOJ's radar, but it's already too late</strong>\n      <span>时间：Sat, 12 Sep 2026 15:26:00 +0200｜来源：The Register｜<a href=\"https://www.theregister.com/systems/2026/09/12/nvidias-groq-acquihire-is-on-the-dojs-radar-but-its-already-too-late/5295986\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <p>Use semiconductors, advanced manufacturing and compute infrastructure as the spine of the story, then compare China’s progress with global competitors and market demand. For this item, test the claim behind “Nvidia's Groq acquihire is on the DOJ's radar, but it's already too late” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>4. A human set a new mathematical record. Then AI came for it</strong>\n      <span>时间：Fri, 11 Sep 2026 19:00:00 +0000｜来源：Science News｜<a href=\"https://www.sciencenews.org/article/human-math-record-twin-primes-openai\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <p>Lead with AI applications, foundation models, agents and governance; verify who is using the system, what measurable gains exist and where governance risks remain. For this item, test the claim behind “A human set a new mathematical record. Then AI came for it” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>5. Anthropic CEO outlines plan to slow AI development</strong>\n      <span>时间：Sat, 12 Sep 2026 19:34:44 +0000｜来源：TechCrunch｜<a href=\"https://techcrunch.com/2026/09/12/anthropic-ceo-outlines-plan-to-pace-the-frontier/\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <p>Turn the item into a reporting test of AI applications, foundation models, agents and governance: capability, implementation, economic value and regulatory consequences. For this item, test the claim behind “Anthropic CEO outlines plan to slow AI development” against primary-source evidence.</p>\n    </article>\n  \n    </div>\n  ",
